// Test block KpiTile (Charts): A tile with one key number, its change from the last period in words and an arrow, an optional sparkline, and a link to the full report.
//
// Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/charts/KpiTile.md and its markup
// (kit/blocks/charts/KpiTile.html, kit/blocks/charts/KpiTile.2.html; source cd6b8b983257), with the vocabulary in
// functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.
//
// Steps (e2e):
//   Then the {kpi} tile shows {value}
//   Then the {kpi} tile change says {text}
//   When I open the {kpi} report
//   When I show the {kpi} numbers as a table
//   Then the {kpi} tile is in the {state} state
// States (from the card): Loaded, Good or bad direction, No comparison yet, Loading, Error, Long numbers, Going
// down. Checked by the state step: Loaded, No comparison yet, Loading, Going down.
import { Registry } from '../../js/registry.js';
import * as p from '../../js/primitives.js';

export const BLOCK = 'KpiTile';
export const ROUTE = '';
export const STATES = ["Loaded", "Good or bad direction", "No comparison yet", "Loading", "Error", "Long numbers", "Going down"];
export const DEFAULT_STATE = 'Loaded';
export const CHECKED_STATES = ["Loaded", "No comparison yet", "Loading", "Going down"];
export const DEMO = ["kit/blocks/charts/KpiTile.html"];
export const SELF_TEST = [
  "Then the \"Revenue\" tile shows \"¥420,000\"",
  "Then the Revenue tile change says \"▲ 9 %\"",
  "Then the Revenue tile is in the \"Loaded\" state",
  "When I show the Revenue numbers as a table",
  "When I open the Revenue report",
];

export const steps = new Registry({ block: BLOCK });

/** The KpiTile block on a page: its controls, found as a person finds them (role and name, label, text). */
export class KpiTile {
  constructor(page, baseURL = '') {
    this.page = page;
    this.baseURL = baseURL;
  }

  async tile(kpi) {
    return p.control(this.page, { role: 'region', name: String(kpi), block: BLOCK });
  }

  async change(kpi) {
    return p.control(await this.tile(kpi), { css: '.badge', block: BLOCK });
  }

  /** Every match, possibly none (for counting). */
  async changeAll(kpi) {
    return (await this.tile(kpi)).locator('.badge');
  }

  async loading(kpi) {
    return p.control(await this.tile(kpi), { css: '[aria-busy="true"]', block: BLOCK });
  }

  async report(kpi) {
    return p.control(await this.tile(kpi), { role: 'link', name: 'View report', block: BLOCK });
  }

  async tableToggle(kpi) {
    return p.control(await this.tile(kpi), { text: 'Show as a table', block: BLOCK });
  }

  /** Check one of the card's states: Loaded, No comparison yet, Loading, Going down. */
  async expectState(state, kpi) {
    const b = this;
    if (state === 'Loaded') {
      await p.expectVisible((await b.change(kpi)).first());
      await p.expectVisible(await b.report(kpi));
    } else if (state === 'No comparison yet') {
      await p.expectCount(await b.changeAll(kpi), 0);
    } else if (state === 'Loading') {
      await p.expectAttribute(await b.tile(kpi), 'aria-busy', 'true');
    } else if (state === 'Going down') {
      await p.expectText(await b.change(kpi), '▼');
    } else {
      throw new Error(`KpiTile has no check for the state '${state}'; checked: ${CHECKED_STATES.join(', ')}`);
    }
  }
}

steps.step("Then the {kpi} tile shows {value}", async (world, { kpi, value }) => {
  const b = new KpiTile(world.page, world.baseURL ?? '');
  await p.expectText(await b.tile(kpi), String(value));
}, { level: 'e2e' });

steps.step("Then the {kpi} tile change says {text}", async (world, { kpi, text }) => {
  const b = new KpiTile(world.page, world.baseURL ?? '');
  await p.expectText(await b.change(kpi), String(text));
}, { level: 'e2e' });

steps.step("When I open the {kpi} report", async (world, { kpi }) => {
  const b = new KpiTile(world.page, world.baseURL ?? '');
  await p.click(await b.report(kpi));
}, { level: 'e2e' });

steps.step("When I show the {kpi} numbers as a table", async (world, { kpi }) => {
  const b = new KpiTile(world.page, world.baseURL ?? '');
  await p.click(await b.tableToggle(kpi));
}, { level: 'e2e' });

steps.step("Then the {kpi} tile is in the {state} state", async (world, { kpi, state }) => {
  const b = new KpiTile(world.page, world.baseURL ?? '');
  await b.expectState(state, kpi);
}, { level: 'e2e' });
